function _buildLogsQS(params) {
  const keyMap = {
    startDate: 'start_date',
    endDate: 'end_date',
    username: 'username',
    project: 'project',
    model: 'model',
    provider: 'provider',
    direction: 'direction',
    sessionId: 'session_id',
    page: 'page',
